<template>
  <div class="page settings-page">
    <PageHeader title="系统设置" subtitle="统一维护分类、品牌、标签、平台与数据偏好。"><button class="pill-button primary-button" :disabled="savingPrefs" @click="savePrefs">{{savingPrefs?'保存中':'保存更改'}}</button></PageHeader>
    <div class="settings-tabs"><button v-for="tab in tabs" :key="tab.key" :class="{active:activeTab===tab.key}" @click="activeTab=tab.key">{{tab.label}}</button></div>
    <AsyncState :loading="loading" :error="error" @retry="load">
      <div class="settings-layout">
        <section class="card dictionary-card"><div class="card-heading"><h2>{{activeLabel}}</h2><PrimaryButton :label="`新建${activeLabel.replace('管理','')}`" :icon="plusIcon" @click="createNew" /></div>
          <template v-if="activeTab==='categories'"><div v-if="categories.length" class="category-tree"><template v-for="root in categories" :key="root.id"><button class="tree-root" :class="{selected:selectedId===root.id}" @click="selectCategory(root)"><span class="branch-mark" /> <strong>{{root.name}}</strong><small>{{root.children?.length||0}} 个子分类</small></button><button v-for="child in root.children" :key="child.id" class="tree-child" :class="{selected:selectedId===child.id}" @click="selectCategory(child)"><span class="branch-line" />{{child.name}}<small>编辑</small></button></template></div><div v-else class="dictionary-empty">暂无分类，创建第一项后会显示在这里。</div></template>
          <template v-else><div v-if="activeItems.length" class="simple-list"><button v-for="item in activeItems" :key="item.id" :class="{selected:selectedId===item.id}" @click="selectSimple(item)"><span v-if="activeTab==='tags'" class="color-dot" :style="{background:(item as TagNode).color||'#b7ff3c'}"/><strong>{{item.name}}</strong><small>{{itemCaption(item)}}</small></button></div><div v-else class="dictionary-empty">暂无数据，点击右上角创建。</div></template>
        </section>
        <aside class="side-stack"><section class="card detail-editor"><h2>{{ selectedId ? `${activeLabel.replace('管理','')}详情` : `新建${activeLabel.replace('管理','')}` }}</h2><el-form label-position="top" class="detail-form">
          <el-form-item label="名称"><el-input v-model="itemForm.name" /></el-form-item>
          <el-form-item v-if="activeTab==='categories'||activeTab==='tags'" label="上级"><el-tree-select v-model="itemForm.parentId" :data="activeTab==='categories'?categories:tags" check-strictly clearable :props="{label:'name',value:'id',children:'children'}" placeholder="无（根节点）"/></el-form-item>
          <el-form-item v-if="activeTab==='brands'" label="别名"><el-input v-model="itemForm.alias" /></el-form-item>
          <el-form-item v-if="activeTab==='brands'" label="首字母"><el-input v-model="itemForm.initial" maxlength="4" /></el-form-item>
          <el-form-item v-if="activeTab==='tags'" label="颜色"><el-color-picker v-model="itemForm.color" /></el-form-item>
          <el-form-item v-if="activeTab==='platforms'" label="平台链接"><el-input v-model="itemForm.link" /></el-form-item>
          <el-form-item label="排序"><el-input-number v-model="itemForm.sort" :min="0" /></el-form-item>
        </el-form><div class="editor-actions"><button class="secondary-button delete-button" :disabled="!selectedId" @click="removeItem">删除</button><PrimaryButton :label="`保存${activeLabel.replace('管理','')}`" :loading="savingItem" @click="saveItem"/></div></section>
        <section class="card preferences-card"><div class="card-heading"><h2>数据偏好</h2><div class="list-actions"><a :href="exportUrl('json')" class="text-button">导出 JSON</a><a :href="exportUrl('csv')" class="text-button">导出 CSV</a></div></div><label><span>默认币种</span><el-select v-model="preferences.currency"><el-option label="CNY" value="CNY"/><el-option label="USD" value="USD"/><el-option label="JPY" value="JPY"/></el-select></label><label><span>日期格式</span><el-select v-model="preferences.dateFormat"><el-option label="YYYY-MM-DD" value="YYYY-MM-DD"/><el-option label="DD/MM/YYYY" value="DD/MM/YYYY"/></el-select></label><label><span>自动备份</span><el-switch v-model="preferences.autoBackupEnabled"/></label><label v-if="preferences.autoBackupEnabled"><span>备份时间</span><el-time-picker v-model="preferences.autoBackupTime" value-format="HH:mm" format="HH:mm"/></label></section></aside>
      </div>
    </AsyncState>
  </div>
</template>

<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'; import { ElMessage,ElMessageBox } from 'element-plus'; import { createBrand,createCategory,createPlatform,createTag,deleteBrand,deleteCategory,deletePlatform,deleteTag,exportUrl,fetchBrands,fetchCategories,fetchPlatforms,fetchPreferences,fetchTags,savePreferences,updateBrand,updateCategory,updatePlatform,updateTag } from '@/api/settings'; import type { BrandItem,CategoryNode,PlatformItem,Preferences,TagNode } from '@/types'; import PageHeader from '@/components/PageHeader.vue'; import PrimaryButton from '@/components/PrimaryButton.vue'; import AsyncState from '@/components/AsyncState.vue'; import plusIcon from '@/assets/icons/plus.svg'
type TabKey='categories'|'brands'|'tags'|'platforms'; type SimpleItem=BrandItem|TagNode|PlatformItem
const tabs:[{key:TabKey,label:string},{key:TabKey,label:string},{key:TabKey,label:string},{key:TabKey,label:string}]=[{key:'categories',label:'分类管理'},{key:'brands',label:'品牌管理'},{key:'tags',label:'标签管理'},{key:'platforms',label:'平台管理'}]
const activeTab=ref<TabKey>('categories'),categories=ref<CategoryNode[]>([]),brands=ref<BrandItem[]>([]),tags=ref<TagNode[]>([]),platforms=ref<PlatformItem[]>([]),selectedId=ref<number>(),loading=ref(true),error=ref(''),savingItem=ref(false),savingPrefs=ref(false); const preferences=reactive<Preferences>({currency:'CNY',dateFormat:'YYYY-MM-DD',autoBackupEnabled:false,autoBackupTime:'02:00'}); const itemForm=reactive<{name:string;parentId?:number|null;alias?:string;initial?:string;color?:string;link?:string;sort:number}>({name:'',sort:0})
// One editor maps the four dictionary DTOs into their dedicated CRUD endpoints while preserving category/tag hierarchy.
const activeLabel=computed(()=>tabs.find(v=>v.key===activeTab.value)?.label||'字典管理'); const activeItems=computed<SimpleItem[]>(()=>activeTab.value==='brands'?brands.value:activeTab.value==='tags'?tags.value:platforms.value)
async function load(){loading.value=true;error.value='';try{const [c,b,t,p,prefs]=await Promise.all([fetchCategories(),fetchBrands(),fetchTags(),fetchPlatforms(),fetchPreferences()]);categories.value=c;brands.value=b;tags.value=t;platforms.value=p;Object.assign(preferences,prefs);if(!selectedId.value&&c[0])selectCategory(c[0])}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function resetForm(){selectedId.value=undefined;Object.assign(itemForm,{name:'',parentId:undefined,alias:'',initial:'',color:'#b7ff3c',link:'',sort:0})}
function selectCategory(item:CategoryNode){selectedId.value=item.id;Object.assign(itemForm,{name:item.name,parentId:item.parentId,sort:item.sort,alias:'',initial:'',link:''})}
function selectSimple(item:SimpleItem){selectedId.value=item.id;Object.assign(itemForm,{name:item.name,parentId:'parentId'in item?item.parentId:undefined,alias:'alias'in item?item.alias:'',initial:'initial'in item?item.initial:'',color:'color'in item?item.color:'#b7ff3c',link:'link'in item?item.link:'',sort:item.sort||0})}
function createNew(){resetForm()}
const itemCaption=(item:SimpleItem)=>activeTab.value==='brands'?(item as BrandItem).alias||'品牌':activeTab.value==='tags'?'标签':(item as PlatformItem).link||'购买平台'
async function saveItem(){if(!itemForm.name.trim()){ElMessage.warning('请输入名称');return}savingItem.value=true;try{if(activeTab.value==='categories'){const p={name:itemForm.name,parentId:itemForm.parentId,sort:itemForm.sort};selectedId.value?await updateCategory(selectedId.value,p):await createCategory(p)}else if(activeTab.value==='brands'){const p={name:itemForm.name,alias:itemForm.alias,initial:itemForm.initial,sort:itemForm.sort};selectedId.value?await updateBrand(selectedId.value,p):await createBrand(p)}else if(activeTab.value==='tags'){const p={name:itemForm.name,parentId:itemForm.parentId,color:itemForm.color,sort:itemForm.sort};selectedId.value?await updateTag(selectedId.value,p):await createTag(p)}else{const p={name:itemForm.name,link:itemForm.link,sort:itemForm.sort};selectedId.value?await updatePlatform(selectedId.value,p):await createPlatform(p)}ElMessage.success('字典项已保存');resetForm();await load()}catch(e){ElMessage.error((e as Error).message)}finally{savingItem.value=false}}
async function removeItem(){if(!selectedId.value)return;try{await ElMessageBox.confirm('删除后可能影响已有记录，确认继续？','删除字典项',{type:'warning'});const actions={categories:deleteCategory,brands:deleteBrand,tags:deleteTag,platforms:deletePlatform};await actions[activeTab.value](selectedId.value);ElMessage.success('已删除');resetForm();await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
async function savePrefs(){savingPrefs.value=true;try{await savePreferences(preferences);ElMessage.success('偏好设置已保存')}catch(e){ElMessage.error((e as Error).message)}finally{savingPrefs.value=false}}
watch(activeTab,resetForm);onMounted(load)
</script>

<style scoped>
.settings-tabs{height:70px;display:flex;align-items:flex-start;gap:18px}.settings-tabs button{height:42px;padding:0 22px;border:0;border-radius:999px;background:transparent;color:var(--dl-text-secondary);font-size:12px;font-weight:600;cursor:pointer}.settings-tabs button.active{background:var(--dl-lime);color:var(--dl-text)}.settings-layout{display:grid;grid-template-columns:minmax(600px,1.8fr) minmax(340px,1fr);gap:24px}.dictionary-card{min-height:658px;padding:20px 22px}.card-heading{display:flex;align-items:center;justify-content:space-between}.card-heading h2{margin:0;font-size:17px}.category-tree,.simple-list{display:grid;gap:10px;margin-top:18px}.category-tree button,.simple-list button{width:100%;height:42px;padding:0 14px;display:flex;align-items:center;gap:10px;border:0;border-radius:12px;background:var(--dl-bg-alt);text-align:left;cursor:pointer}.category-tree button:hover,.simple-list button:hover,.category-tree button.selected,.simple-list button.selected{background:var(--dl-accent-soft)}.category-tree .tree-root{font-size:12px}.category-tree .tree-child{width:calc(100% - 34px);margin-left:34px;background:#f6f7f4;font-size:12px}.category-tree small,.simple-list small{margin-left:auto;color:var(--dl-text-secondary);font-size:10px}.branch-mark{width:9px;height:9px;border-radius:3px;background:var(--dl-text)}.branch-line{width:14px;height:10px;border-left:2px solid var(--dl-muted);border-bottom:2px solid var(--dl-muted);border-radius:0 0 0 4px}.color-dot{width:12px;height:12px;border-radius:50%}.dictionary-empty{height:460px;display:grid;place-items:center;color:var(--dl-muted);font-size:12px}.side-stack{display:grid;gap:24px}.detail-editor{min-height:396px;padding:22px;border:1px solid rgba(23,25,21,.04)}.detail-editor h2{margin:0 0 20px;font-size:17px;color:var(--dl-text)}.detail-form :deep(.el-form-item__label){color:var(--dl-text-secondary);font-size:11px}.detail-form :deep(.el-input__wrapper),.detail-form :deep(.el-select__wrapper){min-height:40px;border-radius:12px;background:var(--dl-bg-alt);box-shadow:0 0 0 1px #e1e4dd inset}.detail-form :deep(.el-input__inner),.detail-form :deep(.el-select__selected-item){color:var(--dl-text)}.detail-form :deep(.el-input__wrapper.is-focus),.detail-form :deep(.el-select__wrapper.is-focused){box-shadow:0 0 0 2px rgba(183,255,60,.72) inset}.detail-form :deep(.el-input-number){width:150px}.detail-form :deep(.el-input-number .el-input__wrapper){background:var(--dl-bg-alt)}.editor-actions{display:flex;justify-content:space-between;margin-top:18px}.secondary-button.delete-button{background:#fff1ef;color:var(--dl-danger)}.secondary-button.delete-button:hover{background:#ffe3df}.preferences-card{min-height:238px;padding:20px 22px}.preferences-card .card-heading{margin-bottom:14px}.preferences-card label{min-height:43px;display:grid;grid-template-columns:1fr 170px;align-items:center;font-size:12px}.preferences-card label>span{color:var(--dl-text-secondary)}.preferences-card :deep(.el-select__wrapper),.preferences-card :deep(.el-input__wrapper){box-shadow:none;background:var(--dl-bg-alt);border-radius:12px}.preferences-card :deep(.el-date-editor){width:170px!important}.preferences-card a{text-decoration:none}
</style>
